INSERT INTO alert (
    id, type, level, status, device_code, device_name, tourism_name,
    description, value, create_time, update_time, handler, remark, handle_time
) VALUES (
    #{id}, #{type}, #{level}, #{status}, #{deviceCode}, #{deviceName}, #{tourismName},
    #{description}, #{value}, #{createTime}, #{updateTime}, #{handler}, #{remark}, #{handleTime}
)

mapper.select:
SELECT *
FROM alert
WHERE id = #{id}

SELECT 

FROM ALERT
WHERE 1=1

    AND ALERT_LEVEL = #{level}


    AND ALERT_STATUS = #{status}

ORDER BY CREATE_TIME DESC

SELECT *
FROM alert

    
        AND type = #{type}
    
    
        AND level = #{level}
    
    
        AND ALERT_STATUS = #{status}
    
    
        AND device_code = #{deviceCode}
    
    
        AND create_time >= #{startTime}
    
    
        AND create_time <= #{endTime}
    

ORDER BY create_time DESC
LIMIT #{offset}, #{limit}

SELECT 

FROM ALERT
WHERE 1=1

    AND TOURISM_NAME = #{tourismName}


    AND DEVICE_CODE = #{deviceCode}


    AND ALERT_TYPE = #{alertType}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

ORDER BY CREATE_TIME DESC

SELECT 
FROM ALERT
WHERE DEVICE_CODE = #{deviceCode}

    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

ORDER BY RECORD_TIME DESC

SELECT 
FROM ALERT
WHERE TOURISM_NAME = #{tourismName}

    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

ORDER BY RECORD_TIME DESC

SELECT COUNT(*)
FROM ALERT

    
        AND DEVICE_CODE = #{params.deviceCode}
    
    
        AND DEVICE_NAME LIKE '%' || #{params.deviceName} || '%'
    
    
        AND TOURISM_NAME = #{params.tourismName}
    
    
        AND ALERT_TYPE = #{params.alertType}
    
    
        AND ALERT_LEVEL = #{params.alertLevel}
    
    
        AND ALERT_STATUS = #{params.status}
    
    
        AND RECORD_TIME >= #{params.startTime}
    
    
        AND RECORD_TIME <= #{params.endTime}

SELECT

FROM ALERT
WHERE ALERT_STATUS = 0

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}

ORDER BY RECORD_TIME DESC

SELECT 
    EXTRACT(HOUR FROM RECORD_TIME) AS hour,
    COUNT(*) AS count
FROM ALERT
WHERE 1=1

    AND TOURISM_NAME = #{tourismName}


    AND DEVICE_CODE = #{deviceCode}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

GROUP BY EXTRACT(HOUR FROM RECORD_TIME)
ORDER BY hour

SELECT 
    ALERT_TYPE AS alertType,
    COUNT(*) AS count
FROM ALERT
WHERE 1=1

    AND TOURISM_NAME = #{tourismName}


    AND DEVICE_CODE = #{deviceCode}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

GROUP BY ALERT_TYPE

SELECT 
    COUNT(*) AS totalCount,
    COUNT(CASE WHEN ALERT_STATUS = 0 THEN 1 END) AS pendingCount,
    COUNT(CASE WHEN ALERT_STATUS = 1 THEN 1 END) AS handledCount,
    COUNT(CASE WHEN ALERT_LEVEL = 3 THEN 1 END) AS highLevelCount
FROM ALERT
WHERE 1=1

    AND TOURISM_NAME = #{tourismName}


    AND DEVICE_CODE = #{deviceCode}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

SELECT 
    ALERT_TYPE as type,
    COUNT(*) as count
FROM ALERT

    
        AND TOURISM_NAME = #{tourismName}
    
    
        AND RECORD_TIME >= #{startTime}
    
    
        AND RECORD_TIME <= #{endTime}
    

GROUP BY ALERT_TYPE
ORDER BY count DESC

SELECT 
    ALERT_LEVEL AS alertLevel,
    COUNT(*) AS count
FROM ALERT
WHERE 1=1

    AND TOURISM_NAME = #{tourismName}


    AND DEVICE_CODE = #{deviceCode}


    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

GROUP BY ALERT_LEVEL
ORDER BY ALERT_LEVEL

SELECT

FROM ALERT

    
        AND TOURISM_NAME = #{tourismName}
    
    
        AND DEVICE_CODE = #{deviceCode}
    
    
        AND ALERT_TYPE = #{alertType}
    
    
        AND ALERT_LEVEL = #{alertLevel}
    
    
        AND ALERT_STATUS = #{alertStatus}
    
    
        AND RECORD_TIME >= #{startTime}
    
    
        AND RECORD_TIME <= #{endTime}
    

ORDER BY RECORD_TIME DESC

SELECT
    HOUR(RECORD_TIME) as hour,
    COUNT(*) as alert_count,
    COUNT(DISTINCT DEVICE_CODE) as device_count
FROM ALERT

    
        AND TOURISM_NAME = #{tourismName}
    
    
        AND DEVICE_CODE = #{deviceCode}
    
    
        AND RECORD_TIME >= #{startTime}
    
    
        AND RECORD_TIME <= #{endTime}
    

GROUP BY HOUR(RECORD_TIME)
ORDER BY hour

SELECT
    ALERT_TYPE as type,
    COUNT(*) as alert_count,
    COUNT(DISTINCT DEVICE_CODE) as device_count,
    AVG(ALERT_LEVEL) as avg_level
FROM ALERT

    
        AND TOURISM_NAME = #{tourismName}
    
    
        AND DEVICE_CODE = #{deviceCode}
    
    
        AND RECORD_TIME >= #{startTime}
    
    
        AND RECORD_TIME <= #{endTime}
    

GROUP BY ALERT_TYPE
ORDER BY alert_count DESC

SELECT
    COUNT(*) as total_count,
    COUNT(DISTINCT DEVICE_CODE) as device_count,
    SUM(CASE WHEN ALERT_STATUS = 0 THEN 1 ELSE 0 END) as unhandled_count,
    AVG(ALERT_LEVEL) as avg_level,
    MAX(ALERT_LEVEL) as max_level
FROM ALERT

    
        AND TOURISM_NAME = #{tourismName}
    
    
        AND DEVICE_CODE = #{deviceCode}
    
    
        AND RECORD_TIME >= #{startTime}
    
    
        AND RECORD_TIME <= #{endTime}

SELECT * FROM ALERT
WHERE DEVICE_CODE = #{deviceCode}

    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

ORDER BY RECORD_TIME DESC

SELECT * FROM ALERT
WHERE TOURISM_NAME = #{tourismName}

    AND RECORD_TIME >= #{startTime}


    AND RECORD_TIME <= #{endTime}

ORDER BY RECORD_TIME DESC

SELECT COUNT(*) FROM ALERT
WHERE ALERT_STATUS = 0

    AND DEVICE_CODE = #{deviceCode}


    AND TOURISM_NAME = #{tourismName}
